15	const { spawn, execFileSync } = require('child_process');
16	const fs = require('fs'), path = require('path'), crypto = require('crypto'), os = require('os');
17	const ROOT = path.resolve(__dirname, '../../..');
18	const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.json': 'application/json', '.woff2': 'font/woff2', '.png': 'image/png' };
