1	// Tập 7 · C3 · s06-stack (B06, KEY-3) · vòng 2: vạch mức 15 năm (ink-muted) qua hai thanh; đồ thị thấy thanh 30 năm NGẮN hơn ("required") rồi dâng
2	// lên $2,948, vượt vạch một lát (warn); mỗi nhịp lát tách khỏi đỉnh thanh 30 năm, bay sang the stack (15 lần) → "the stack: $21,622 extra paid …".
3	import { setup, home, nameTag, theStack, stackSet, BUNDLE_TH, modeLook, chrome, label, kf, show, ease, C, THREE } from '/episodes/ep007/world/c3kit.js';
4	import { PayBar, TRACK } from '/episodes/ep007/world/obj7.js';
5	
6	const SEG = '/episodes/ep007/world/c3/s06-stack/';
7	const SCALE = 1 / 1230;   // USD/tháng → chiều cao thế giới (thanh khoản trả); chồng dùng thang bó riêng (BUNDLE_TH mỗi năm)
8	const BAR_W = 0.8, BAR_D = 0.5, FLY_W = 0.9, FLY_D = 0.6;
9	
10	export async function boot(res) {
11	  const poses = {
12	    wS: { pos: [-4.4, 2.7, 8.4], tgt: [-0.6, 1.1, 0], fov: 38, chart: 0 },
13	    cS: { pos: [-0.3, 1.5, 20], tgt: [-0.3, 1.5, 0], fov: 19, chart: 1 },
14	  };
15	  const { S, CL, D, cue, st, O, renderer, scene, floor, CAM } = await setup(SEG, res, poses);
16	  const G = CL._geom, b = cue;
17	  // trái → phải: nhà · the stack · thanh 15 năm · thanh 30 năm (chồng nằm giữa nhà và thanh: lát bay từ thanh 30 năm qua đỉnh thanh 15 năm vào chồng)
18	  const hm = home(scene, { x: -2.8 }), stack = theStack(scene, G, { x: -1.1 });
19	  const bar15 = PayBar({ w: BAR_W, d: BAR_D, scale: SCALE, name: '15-year' }), bar30 = PayBar({ w: BAR_W, d: BAR_D, scale: SCALE, name: '30-year' });
20	  bar15.position.set(0.2, 0, 0); bar30.position.set(1.4, 0, 0); scene.add(bar15, bar30);
21	  // vạch mức 15 năm: ink-muted, đứng yên, trước mặt hai thanh, kéo qua cả hai (hiện từ trái sang ở "finishing")
22	  const top15 = bar15.topY(G.pay15), lx0 = bar15.position.x - BAR_W / 2 - 0.15, lx1 = bar30.position.x + BAR_W / 2 + 0.15, LZ = BAR_D / 2 + 0.02;
23	  const lvGeo = new THREE.BoxGeometry(1, 0.035, 0.02); lvGeo.translate(0.5, 0, 0);
24	  const level = new THREE.Mesh(lvGeo, new THREE.MeshBasicMaterial({ color: TRACK.mark }));
25	  level.position.set(lx0, top15, LZ); level.userData.checks = { role: 'mark', key: 'level-15', value: G.pay15 }; scene.add(level);
26	  // lát đang bay (tối đa 2 cùng lúc: FLY 0,8 s, nhịp ~0,42 s): bắt đầu TRÙNG lát warn trên đỉnh thanh 30 năm, nhấc lên, vòng ra trước thanh 15 năm,
27	  // thành bó trên đỉnh chồng
28	  const flyMat = new THREE.MeshStandardMaterial({ color: TRACK.warn, roughness: 0.8, emissive: new THREE.Color(TRACK.warn), emissiveIntensity: 0.25 });
29	  const flies = [0, 1, 2].map(() => { const m = new THREE.Mesh(new THREE.BoxGeometry(FLY_W, BUNDLE_TH, FLY_D), flyMat); m.castShadow = true; scene.add(m); return m; });
30	  const sliver = (G.pay30on15 - G.pay15) * SCALE;
31	  const path = (k, p) => {   // p ∈ [0,1] (sau pha nhấc): toạ độ thế giới của lát k
32	    const ys = top15 + sliver / 2 + 0.22, ye = k * BUNDLE_TH + BUNDLE_TH / 2;
33	    return [bar30.position.x + (stack.position.x - bar30.position.x) * p, ys + (ye - ys) * p ** 4 + 0.4 * Math.sin(Math.PI * p), 0.75 * Math.sin(Math.PI * p)];
34	  };
35	  const LIFT = 0.18;
36	
37	  function frame(t) {
38	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
