      claims: ['yearly_lump_months', 'yearly_lump_late'] });
    log.roi['a2.four'] = [fx0, Math.max(fy0, gy1) + 20, fx0 + 1100, Math.max(fy0, gy1) + 90];
    chrome(O);
    st.compose(); log.camMoving = CAM.moving(t); return log;
  }
  return { canvas: st.out, frame };
}

